CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, description text, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, capacity integer NOT NULL CHECK(capacity >= 0), planned_budget numeric NOT NULL CHECK(planned_budget >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(start_at < end_at)); CREATE INDEX events_owner_idx ON events(owner_id);
CREATE TABLE tasks (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, title text NOT NULL, description text, status text NOT NULL CHECK(status IN ('todo','in_progress','completed')), priority text NOT NULL CHECK(priority IN ('low','medium','high')), due_at timestamptz, dependency_task_id uuid REFERENCES tasks(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX tasks_event_idx ON tasks(event_id);
CREATE TABLE guests (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, name text NOT NULL, email text, status text NOT NULL CHECK(status IN ('invited','accepted','declined','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX guests_event_idx ON guests(event_id);
CREATE TABLE budget_categories (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, name text NOT NULL, planned_amount numeric NOT NULL CHECK(planned_amount >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,name));
CREATE TABLE expenses (id uuid PRIMARY KEY, budget_category_id uuid NOT NULL REFERENCES budget_categories(id) ON DELETE RESTRICT, name text NOT NULL, amount numeric NOT NULL CHECK(amount > 0), incurred_on date NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX expenses_category_idx ON expenses(budget_category_id);
CREATE TABLE schedule_items (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, name text NOT NULL, description text, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(start_at < end_at));
CREATE TABLE vendors (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, name text NOT NULL, contact_name text, contact_email text, contract_amount numeric NOT NULL CHECK(contract_amount >= 0), status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE vendors ADD COLUMN category text, ADD COLUMN contact_phone text, ADD COLUMN contract_status text NOT NULL DEFAULT 'active', ADD COLUMN contract_url text, ADD COLUMN notes text;
CREATE TABLE vendor_payments (id uuid PRIMARY KEY, vendor_id uuid NOT NULL REFERENCES vendors(id) ON DELETE RESTRICT, amount numeric NOT NULL CHECK(amount > 0), paid_on date NOT NULL, reference text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE vendor_payments ADD COLUMN payment_date date, ADD COLUMN payment_method text, ADD COLUMN notes text, ADD COLUMN status text NOT NULL DEFAULT 'paid'; UPDATE vendor_payments SET payment_date=paid_on; ALTER TABLE vendor_payments ALTER COLUMN payment_date SET NOT NULL; CREATE INDEX vendor_payments_vendor_idx ON vendor_payments(vendor_id);
CREATE TABLE notifications (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, kind text NOT NULL, source_type text NOT NULL, source_id uuid NOT NULL, state_key text NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,kind,source_type,source_id,state_key));
CREATE TABLE audit_logs (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE, actor_user_id uuid NOT NULL REFERENCES users(id), resource_type text NOT NULL, resource_id uuid NOT NULL, action text NOT NULL CHECK(action IN ('create','update','delete','status_change')), details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX audit_event_idx ON audit_logs(event_id,created_at DESC);
